-- Echo Coffee menu: 85 exact SKUs representing 68 menu items. Apply after 0010 and 0009.
-- Existing paid order snapshots and customer data are not modified.
ALTER TABLE pos_products ADD COLUMN category_zh TEXT NOT NULL DEFAULT '';
ALTER TABLE pos_products ADD COLUMN size_label TEXT NOT NULL DEFAULT 'ONE';
ALTER TABLE pos_products ADD COLUMN item_note TEXT NOT NULL DEFAULT '';
ALTER TABLE pos_products ADD COLUMN source_image TEXT NOT NULL DEFAULT '';
ALTER TABLE pos_products ADD COLUMN best_seller INTEGER NOT NULL DEFAULT 0;
CREATE TABLE pos_menu_options(group_code TEXT NOT NULL,option_code TEXT NOT NULL,option_vi TEXT NOT NULL,option_zh TEXT NOT NULL,price_delta INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(group_code,option_code));
CREATE TABLE pos_product_modifiers(product_id TEXT NOT NULL,group_code TEXT NOT NULL,min_select INTEGER NOT NULL,max_select INTEGER NOT NULL,PRIMARY KEY(product_id,group_code));
-- Retire untouched legacy demo products; keep rows so old snapshots and stock logs remain readable.
UPDATE pos_products SET active=0,version=version+1,updated_at='2026-09-25T00:00:00.000Z' WHERE id IN ('101','102','103','104','105','106','107','108','109','110','111','112','113') AND sku LIKE 'PT%' AND updated_at='2026-09-24T00:00:00.000Z';
UPDATE pos_store_config SET store_name='Echo Coffee',store_name_cn='Echo Coffee',transfer_prefix='EC',logo_png='/brands/echo-coffee.jpg',updated_at='2026-09-25T00:00:00.000Z',version=version+1 WHERE id=1 AND store_name='TIỆM SÍU LẬP PHÁT TÀI' AND updated_by='system' AND logo_png='';
